RE_LOI_GOI = re.compile(r"^((?:[A-Za-z_]\w*=[\w./:-]*\s+)*)(?:[\w./-]*/)?python(?:\d+(?:\.\d+)*)?(?:\s+-[BuIsSEOqb]+)*"
